set -e
JOB=/home/etherealogic_2/adws-pipeline-skill/artifacts/job_20260812_0001
WT=/home/etherealogic_2/adws-pipeline-skill-adws-job_20260812_0001
NOW=$(date -u +%Y-%m-%dT%H:%M:%SZ)
node -e '
const fs=require("fs"), crypto=require("crypto");
const JOB=process.argv[1], WT=process.argv[2], NOW=process.argv[3];
// 1. coverage join by id
const specs=JSON.parse(fs.readFileSync(JOB+"/test/attempt_1/skills/criteria-to-checks/skill_trace.json")).output.check_specs.map(s=>s.check_id);
const po=JSON.parse(fs.readFileSync(JOB+"/test/attempt_1/phase_output.json"));
const covered=new Set(po.checks.map(c=>c.check_id));
const missing=specs.filter(id=>!covered.has(id));
if(missing.length){ console.error("UNCOVERED spec ids:", missing); process.exit(1); }
console.log("coverage join: all", specs.length, "spec ids present in", po.checks.length, "checks");
const verdicts=po.checks.map(c=>c.check_id+":"+c.verdict+(c.pass?"":"(pass=false)"));
console.log("check verdicts:", verdicts.join(" "));
const anyFail=po.checks.some(c=>c.verdict==="fail");
if(anyFail){ console.error("check verdict fail present"); process.exit(1); }
// 2. consensus shapes
const critic=JSON.parse(fs.readFileSync(JOB+"/test/attempt_1/consensus/critic.json"));
const adv=JSON.parse(fs.readFileSync(JOB+"/test/attempt_1/consensus/advocate.json"));
console.log("critic:", critic.verdict, "| has resolution key:", "resolution" in critic, "| findings:", critic.findings.length);
console.log("advocate:", adv.verdict, "| dissent:", adv.dissent, "| resolution:", adv.resolution);
if(critic.verdict!=="pass" || adv.verdict!=="pass" || adv.dissent!==null){ console.error("consensus not clean"); process.exit(1); }
// 3. close test gate
const pmp=JOB+"/test/attempt_1/phase_manifest.json";
const pm=JSON.parse(fs.readFileSync(pmp));
pm.gate_result="pass";
const t0=Date.parse(pm.started_at), t1=Date.parse(pm.completed_at);
pm.provenance={ model_id:null, cost_usd:null, tokens_in:null, tokens_out:null, elapsed_ms:542037, tool_call_count:44, timeout:false, cancel:false, started_at:pm.started_at, completed_at:pm.completed_at, wall_clock_s:Math.round((t1-t0)/1000), agent:"adws-tester", model_tier_requested:"sonnet" };
fs.writeFileSync(pmp, JSON.stringify(pm,null,2));
// 4. run_manifest: operator-directed stop after test gate pass
const files=["adws-pipeline/scripts/execution-report.js","adws-pipeline/references/phase-gates.md","adws-pipeline/references/artifact-layout.md","adws-pipeline/references/troubleshooting.md"];
const digests=files.map(f=>({ path:f, sha256:crypto.createHash("sha256").update(fs.readFileSync(WT+"/"+f)).digest("hex") }));
const rmp=JOB+"/run_manifest.json";
const rm=JSON.parse(fs.readFileSync(rmp));
rm.final_status="canceled";
rm.failure_reason="OPERATOR_CANCEL";
rm.completed_at=NOW;
rm.carry_over={ retained:true, resumable:true, resumable_reason:null, worktree_path:WT, branch_name:rm.branch_name, gated_through:"test", files:digests };
rm.operator_notes=rm.operator_notes+" OUTCOME: plan, build, and test gates all PASSED (test gate decided pass at "+NOW+" — 4/4 criteria verified with red baselines, criteria-to-checks pass, Critic pass, no Advocate dissent; one gate_weak supplementary parity-corpus check surfaced as a warn: the corpus pins schema_version 1.4.0 and the change bumps it to 1.5.0, decisions/exit codes unchanged). Run then canceled by operator directive before the review phase, per the launch instruction. execution-report.js NOT run and evidence NOT archived, both by explicit operator instruction; worktree retained and resumable.";
fs.writeFileSync(rmp, JSON.stringify(rm,null,2));
console.log("test gate closed: PASS; run recorded canceled/OPERATOR_CANCEL with resumable carry_over (gated_through: test)");
' $JOB $WT $NOW
